function onAction(a,el){let v=el.dataset.value;switch(a){case 'studioclear':{let [g,k]=v.split(':');studio[g][k]=[];studioStore();redrawStudioChoice();break;}case 'studiosave':{const title=prompt('Name deiner Analyse (nur auf diesem Gerät):','Mein Poker-Vergleich');if(title&&title.trim()){studio.saved.push({title:title.trim().slice(0,70),metric:studio.metric,a:clone(studio.a),b:clone(studio.b)});studioStore();draw()}break;}case 'studioload':{const x=studio.saved[Number(v)];if(x){studio.metric=x.metric;studio.a=clone(x.a);studio.b=clone(x.b);studioStore();draw()}break;}case 'studiodelete':{studio.saved.splice(Number(v),1);studioStore();draw();break;}case 'studioreset':{const saved=studio.saved;studio=studioInit();studio.saved=saved;studioStore();draw();break;}case 'menu':state.menuOpen=!state.menuOpen;draw();break;case 'go':goto(v);break;case 'back':previous();break;case 'historyteaser':{if(!['yearbook','replay','moments','records','field','compare'].includes(v))break;goto('history');const tile=document.querySelector('.history-entry-tile[data-view="'+v+'"]');if(tile)tile.click();break;}case 'openyear':state.historyYear=Number(v);state.manageRound=1;state.raceRound=1;goto('history');break;case 'historyyear':state.historyYear=Number(v);state.manageRound=1;state.raceRound=1;draw();break;case 'tab':state.tab=v;draw();jumpToTarget('selected-stat-tool');break;case 'statsrounds':state.tab=v;goto('stats',{},'selected-stat-tool');break;case 'insightchooseyear':case 'insightchooseplayer':{const panel=document.querySelector('.tool-choice-panel');if(panel){panel.open=true;panel.scrollIntoView({behavior:'smooth',block:'center'});}break;}case 'profile':if(!v)return;state.profile=v;goto('profile');break;case 'challenge':state.rivalA=v;state.rivalB=names.find(x=>x!==v)||v;state.tab='rivals';goto('stats',{},'selected-stat-tool');break;case 'round':state.manageRound=Number(v);draw();break;case 'sort':{const id=el.dataset.table,key=v,old=state.sort[id];state.tablePages[id]=0;state.sort[id]={key,dir:old?.key===key&&old.dir==='asc'?'desc':'asc'};draw();break;}case 'tablepage':{const id=el.dataset.table;state.tablePages[id]=Math.max(0,(state.tablePages[id]||0)+Number(v));draw();break;}case 'openplayers':modal='players';draw();break;case 'openyears':modal='years';draw();break;case 'toggleseries':state.hiddenSeries=state.hiddenSeries.includes(v)?state.hiddenSeries.filter(x=>x!==v):[...state.hiddenSeries,v];draw();break;case 'toggleyear':{let n=Number(v);state.selectedYears=state.selectedYears.includes(n)?state.selectedYears.filter(x=>x!==n):[...state.selectedYears,n].sort((a,b)=>a-b);state.selected=state.selected.filter(p=>db.editions.some(ed=>(!state.selectedYears.length||state.selectedYears.includes(ed.year))&&ed.players.includes(p)));state.hiddenSeries=[];draw();break;}case 'clearyears':state.selectedYears=[];draw();break;case 'closemodal':modal=false;draw();break;case 'toggle':state.selected=state.selected.includes(v)?state.selected.filter(x=>x!==v):[...state.selected,v];state.hiddenSeries=[];draw();break;case 'clearplayers':state.selected=[];draw();break;case 'resetfilters':state.year='all';state.selectedYears=[];state.selected=[];draw();break;case 'resetdemo':if(confirm('Alle aktuell importierten Archivdaten durch die 17 bestätigten Turnierjahrgänge ersetzen?')){db=clone(seed);localStorage.removeItem('poker-demo-data-v1');state.year='all';state.selected=[];draw()}break;case 'export':download('baergsunne-poker-originalarchiv-2007-2026.json',JSON.stringify(db,null,2));break;case 'racestep':{const e=eyear(state.year==='all'?state.historyYear:state.year)||db.editions.at(-1);state.raceRound=Math.min(e.round_count,Math.max(1,state.raceRound+Number(v)));draw();break;}case 'saveround':{alert('Nur autorisierte Admins dürfen Rundenergebnisse speichern.');break;/* disabled public write */let select=[...document.querySelectorAll('[data-sandbox-place]')].map(x=>x.value);if(select.some(x=>!x)||new Set(select).size!==10){alert('Bitte jeden Spieler genau einmal auswählen.');return}let rr=getSandbox();rr[state.manageRound-1]=select.map((player,i)=>({player,place:i+1,points:sandboxPoints[i]}));saveSandbox(rr);draw();break}case 'clearround':{alert('Nur autorisierte Admins dürfen Rundenergebnisse löschen.');break;/* disabled public write */let rr=getSandbox();rr[state.manageRound-1]=null;saveSandbox(rr);draw();break}case 'clearsandbox':alert('Nur autorisierte Admins dürfen Daten zurücksetzen.');break;/*if(confirm('Die gesamte lokale Championship-2026-Sandbox löschen?')){localStorage.removeItem(sandboxKey);draw()}*/break;default:break;}}
