function validateArchive(data){
 if(!data||!Array.isArray(data.players)||!Array.isArray(data.editions)||data.editions.length<1)throw Error('Spieler/Jahrgänge fehlen.');
 const ids=new Set(data.players.map(p=>p.id));if(ids.size!==data.players.length)throw Error('Spieler-IDs nicht eindeutig.');
 const ys=new Set();for(const e of data.editions){if(!Number.isInteger(e.year)||ys.has(e.year))throw Error('Ungültiger oder doppelter Jahrgang');ys.add(e.year);
  if(!Array.isArray(e.players)||!Array.isArray(e.rounds)||!Array.isArray(e.official_standings)||e.round_count!==e.rounds.length||e.players.length<2)throw Error('Ungültiger Jahrgang '+e.year);
  if(e.players.some(p=>!ids.has(p))||new Set(e.players).size!==e.players.length)throw Error('Spieleridentität inkonsistent '+e.year);
  if(!Array.isArray(e.scoring?.points_by_place)||e.scoring.points_by_place.length<e.players.length)throw Error('Punktetabelle fehlt '+e.year);
  if(e.official_standings.length!==e.players.length||new Set(e.official_standings.map(s=>s.player_id)).size!==e.players.length)throw Error('Schlussklassement inkonsistent '+e.year);
  for(const r of e.rounds){if(!Array.isArray(r.results)||r.results.length!==e.players.length)throw Error('Runde unvollständig '+e.year);
   if(r.results.some(x=>!ids.has(x.player_id)||!Number.isInteger(x.place)||!Number.isFinite(x.points))||new Set(r.results.map(x=>x.player_id)).size!==e.players.length)throw Error('Rundenplätze inkonsistent '+e.year);
  }
  for(const st of e.official_standings){const total=e.rounds.reduce((sum,r)=>sum+r.results.find(x=>x.player_id===st.player_id)?.points,0);if(!Number.isFinite(total)||total!==st.points)throw Error('Jahressumme stimmt nicht: '+e.year+' '+st.player_id)}
 }
}
