let touchStart=null;document.addEventListener('touchstart',e=>{if(!e.target.closest('.page')||e.target.closest('.table-scroll,.heat-scroll,.tabrail,.chart-scroll,.yearrail,.modal-backdrop,.round-form,.history-carousel-viewport,.history-carousel-control,.history-replay-viewport,.history-replay-control')){touchStart=null;return}let t=e.touches[0];touchStart={x:t.clientX,y:t.clientY};},{passive:true});document.addEventListener('touchend',e=>{if(!touchStart||state.page!=='history')return;const t=e.changedTouches[0],dx=t.clientX-touchStart.x,dy=t.clientY-touchStart.y;touchStart=null;if(Math.abs(dx)>80&&Math.abs(dx)>Math.abs(dy)*1.7){let index=years.indexOf(state.historyYear),next=Math.max(0,Math.min(years.length-1,index+(dx<0?1:-1)));if(index!==next){state.historyYear=years[next];state.year=String(years[next]);state.manageRound=1;state.raceRound=1;draw()}}},{passive:true});
